card_tpl='<article class="article-card"><a href="/blog/{slug}/"><img loading="lazy" src="{image}" alt="{title} cover image"></a><div class="article-card-body"><p class="card-kicker">{cat}</p><h3><a href="/blog/{slug}/">{title}</a></h3><p>{summary}</p><div class="article-meta"><span>{date}</span><span>7 min read</span></div><a class="read-more" href="/blog/{slug}/">Read More →</a></div></article>'
cards=''.join(card_tpl.format(slug=a['slug'],image=a['image'],title=escape(a['title']),cat=escape(a['category']),summary=escape(a['summary']),date=DATE) for a in articles)
s=s.replace('<div class="latest-grid">','<div class="latest-grid">'+cards,1)
items=[]
for m in re.finditer(r'<h3><a href="/blog/([^/]+)/">([^<]+)</a></h3>',s):
    if m.group(1) not in [x[0] for x in items]: items.append((m.group(1),m.group(2)))
obj={'@context':'https://schema.org','@type':'ItemList','name':'ShopLovaNest Sexual Wellness Guides','url':BASE+'/blog/','numberOfItems':len(items),'itemListElement':[{'@type':'ListItem','position':i+1,'url':f'{BASE}/blog/{slug}/','name':title} for i,(slug,title) in enumerate(items)]}
s=re.sub(r'<script type="application/ld\+json">\{"@context": "https://schema.org", "@type": "ItemList".*?</script>','<script type="application/ld+json">'+json.dumps(obj)+'</script>',s,count=1,flags=re.S)
